#![cfg(unix)]
use moloch_live_runtime::{dispatch::DispatchLog,execution_distribution::*,feedback,fundamental_policy::*};
use moloch_replay::session::{Session,ExclusiveLock};
use baal_transport_service::{Receipt,RequestSpec,Scope,Permit};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{collections::BTreeSet,path::PathBuf,sync::Arc};
const BASE:u64=1_792_022_400_000;
fn stamp(ms:u64)->String{chrono::DateTime::from_timestamp_millis((BASE+ms)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash<T:serde::Serialize+?Sized>(v:&T)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn raw_sha(v:&[u8])->String{format!("{:x}",Sha256::digest(v))}
fn config()->AcquisitionConfig{AcquisitionConfig{cohort_id:"synthetic-terminal-acquisition".into(),maximum_pending:16,retained_completed:8}}
struct F{bank:Session,log:DispatchLog,shadow:AcquisitionShadow,store:Cohorts,scope:Scope,trust:BTreeSet<String>,path:PathBuf,seq:u64,rows:Vec<Value>}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.path);}}
impl F {
 fn new()->Self {
  let path=std::env::temp_dir().join(format!("fundamental-acquisition-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&path).unwrap();let owner=Arc::new(ExclusiveLock::acquire(&path.join("owner.lock")).unwrap());
  let scope=Scope{tournament_id:"cup".into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"101".into())].into()};
  let policy=json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"20.000000","quantity":4,"maximumMarkets":3,"minimumSpreadTicks":2,"entryStopAt":stamp(1_000_000)});
  let seed=json!({"runId":"acquisition-fixture","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":stamp(0)});
  let bank=Session::open_live(&path.join("bank"),&policy,&seed).unwrap();let log=DispatchLog::open(&path.join("dispatch.ndjson")).unwrap();let shadow=AcquisitionShadow::new(&bank,&log,&scope,config(),BASE).unwrap();let mut store=Cohorts::initialize(&path,&bank,&log,owner).unwrap();
  let node=json!({"market_id":"101","root":{"node_type":"contract","node_id":"201","contract_id":"201","title":"Synthetic Republican Party Winner","contract_type":"Election Outcome","contract_details":{"contractType":"Election Outcome","resolutionType":"Party Winner","winnerName":"Republican Party","electionDate":"2026-11-03","officeLevel":"Federal","usState":"Synthetic","raceId":1,"stageId":2,"raceName":"Synthetic","raceStage":"General"},"settled_with":null,"settlement_date":null}});
  let timing=json!({"tournamentId":"cup","marketId":"101","contractId":"201","scheduledSettlementAt":stamp(3_600_000)});
  let originals=vec![b"synthetic uncalibrated forecast".to_vec(),b"synthetic ballot source".to_vec(),serde_json::to_vec(&node).unwrap(),serde_json::to_vec(&timing).unwrap()];let hashes=originals.iter().map(|b|raw_sha(b)).collect::<Vec<_>>();
  let sources=["forecast","official_ballot","official_contract_node","official_settlement_timing"].iter().enumerate().map(|(i,k)|json!({"kind":k,"url":format!("https://fixture.invalid/{k}"),"sha256":hashes[i],"publishedAtMs":BASE-100,"observedAtMs":BASE-50,"maximumAgeMs":86_400_000})).collect::<Vec<_>>();
  let review:ReviewInput=serde_json::from_value(json!({"version":2,"reviewerId":"fixture-owner","assumptionLabel":"Synthetic ordinary payout assumption; no calibration or financial activation","runId":"acquisition-fixture","bankManifestSha256":bank.manifest_hash(),"tournamentId":"cup","marketId":"101","exchangeId":"101","contractId":"201","side":"YES","officialContractRootSha256":official_contract_root_sha256(&node).unwrap(),"ordinaryProbability":"0.800000","exceptionalProbabilityAllowance":"0.000000","minimumExceptionalPayout":"0.000000","marginPerShare":"0.010000","maximumPrincipal":"10.000000","maximumQuantity":4,"reviewedAtMs":BASE,"expiresAtMs":BASE+1_000_000,"holdUntilMs":BASE+3_600_000,"payoutMappingIsOperatorAssumption":true,"revokeExisting":false,"sources":sources,"valuationObjective":{"kind":"terminalSettlement","timingSourceSha256":hashes[3],"timingJsonPointer":"/scheduledSettlementAt","scheduledSettlementAtMs":BASE+3_600_000,"delayPolicy":"holdForActualSettlement"}})).unwrap();
  let trust=[review_sha256(&review).unwrap()].into();let refs=originals.iter().zip(&hashes).map(|(bytes,sha256)|SourceBytes{sha256,bytes}).collect::<Vec<_>>();let reviewed=Reviewed::verify(review,&refs,&trust,BASE).unwrap();store.install(reviewed,&bank,&log,BASE).unwrap();
  Self{bank,log,shadow,store,scope,trust,path,seq:0,rows:Vec::new()}
 }
 fn put(&mut self,mut event:Value,at:u64){if event.get("receivedAt").is_none(){event["receivedAt"]=json!(stamp(at));}event["processedAt"]=json!(stamp(at));self.seq+=1;self.bank.accept("moloch-live",self.seq,&event).unwrap();self.shadow.observe_committed(&self.bank,"moloch-live",self.seq,&event).unwrap();}
 fn book(&mut self,at:u64,version:u64){self.put(json!({"type":"book","book":{"tournamentId":"cup","marketId":"101","exchangeId":"101","sequence":version.to_string(),"sourceAt":stamp(at),"requestStartedAt":stamp(at),"receivedAt":stamp(at),"bids":[{"price":"0.400000","quantity":100}],"asks":[{"price":"0.450000","quantity":100}]}}),at);}
 fn start(&mut self,n:u64,tagged:bool)->Value {
  self.book(0,1);self.book(3000,2);let q=self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["action"]=="buy"&&q["side"]=="YES").unwrap();self.intent(&q,n,tagged,3000,20000);q
 }
 fn intent(&mut self,q:&Value,n:u64,tagged:bool,at:u64,permit_until:u64){
  let id=q["id"].as_u64().unwrap();let body=json!({"idempotencyKey":format!("acquisition-fixture:{id}"),"tournamentId":"cup","exchangeId":"101","side":if q["side"]=="YES"{"yes"}else{"no"},"action":q["action"],"quantity":n,"price":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap(),"expirationDate":chrono::DateTime::from_timestamp_millis(q["expiresAt"].as_i64().unwrap()).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)});
  let spec=RequestSpec{method:"POST".into(),endpoint:"/orders".into(),body_json:Some(serde_json::to_string(&body).unwrap()),body:Some(body)};
  let tag=if tagged{assert!(matches!(self.store.bind_quantity(&self.bank,&self.log,&self.scope,id,n,&spec,&self.trust,BASE+at).unwrap(),Decision::Entry{..}));self.store.durable_tag(id).unwrap()}else{Value::Null};
  let permit=Permit{run_id:"acquisition-fixture".into(),intent_id:id.to_string(),owner:"Codex".into(),expires_at_ms:BASE+permit_until,maximum_quantity:n as u32,maximum_cost:moloch_replay::money(baal_transport_service::decimal_units(q["price"].as_str().unwrap()).unwrap()*n as i128)};
  self.log.append(json!({"kind":"intent","qid":id,"quote":q,"spec":spec,"permit":permit,"fundamental":tag})).unwrap();self.log.append(json!({"kind":"attempt","qid":id,"at":stamp(at),"captureAtMs":BASE+at,"nativeHead":self.bank.durable_head()})).unwrap();let tracked=self.shadow.track_attempt(&self.bank,&self.log,id,BASE+at).unwrap();assert_eq!(tracked,tagged);
 }
 fn r(endpoint:String,data:Value,start:u64,end:u64)->Receipt{Receipt{endpoint,status:200,request_started_at:stamp(start),received_at:stamp(end),data}}
 fn actual(q:&Value)->String{format!("90{}",q["id"].as_u64().unwrap())}
 fn ack(&mut self,q:&Value,n:u64,at:u64){let r=Self::r("/orders".into(),json!({"orderId":Self::actual(q),"exchangeId":"101","side":if q["side"]=="YES"{"yes"}else{"no"},"action":q["action"],"price":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap(),"quantity":n}),at-1,at);let e=feedback::acknowledgment(q,&r,&stamp(at)).unwrap();self.log.append(json!({"kind":"ack","qid":q["id"],"receipt":r})).unwrap();self.put(e,at);}
 fn tape(&self,q:&Value,start:u64,end:u64)->Receipt{let total=self.rows.iter().map(|r|r["quantity"].as_i64().unwrap()).sum::<i64>();Self::r(format!("/orders/{}/fills?limit=200",Self::actual(q)),json!({"orderId":Self::actual(q),"exchangeId":"101","tournamentId":"cup","coverage":{"complete":true,"projectedThroughSequence":99999},"pagination":{"hasMore":false,"nextCursor":null},"totalQuantityFilled":total,"data":self.rows}),start,end)}
 fn fill(&mut self,q:&Value,n:u64,price:f64,executed:u64,observed:u64,id:u64){self.rows.push(json!({"id":id,"side":if q["side"]=="YES"{"yes"}else{"no"},"quantity":if q["side"]=="YES"{n as i64}else{-(n as i64)},"price":price,"filledAt":stamp(executed)}));let tape=self.tape(q,observed-1,observed);for e in feedback::fills(q,&Self::actual(q),"cup",&tape,&stamp(observed)).unwrap(){self.put(e,observed);}}
 fn close(&mut self,q:&Value,start:u64,at:u64,append:bool)->(Receipt,Receipt){let q=self.bank.engine().order_records().into_iter().find(|x|x["id"]==q["id"]).unwrap();let total=self.rows.iter().map(|r|r["quantity"].as_i64().unwrap().unsigned_abs()).sum::<u64>();let order=Self::r(format!("/orders/{}",Self::actual(&q)),json!({"id":Self::actual(&q),"exchangeId":"101","tournamentId":"cup","side":if q["side"]=="YES"{"yes"}else{"no"},"action":q["action"],"priceLimit":serde_json::from_str::<Value>(q["price"].as_str().unwrap()).unwrap(),"quantity":q["quantity"],"quantityFilled":total,"open":false,"terminalReasonCode":"Canceled"}),start,start+1);let tape=self.tape(&q,start+1,at);for e in feedback::fills(&q,&Self::actual(&q),"cup",&tape,&stamp(at)).unwrap(){self.put(e,at);}let e=feedback::terminal(&q,&Self::actual(&q),"cup",&order,&tape,&stamp(at)).unwrap().unwrap();self.put(e,at);if append{self.closed_row(&q,&order,&tape);} (order,tape)}
 fn closed_row(&mut self,q:&Value,order:&Receipt,tape:&Receipt){self.log.append(json!({"kind":"closed","qid":q["id"],"orderReceiptHash":feedback::digest(order).unwrap(),"fillReceiptHash":feedback::digest(tape).unwrap()})).unwrap();}
 fn outcome(&self,q:&Value,at:u64)->AcquisitionOutcome{self.shadow.outcome(q["id"].as_u64().unwrap(),BASE+at).unwrap()}
 fn confirm(&mut self,q:&Value,start:u64,at:u64){let(o,t)=self.close(q,start,at,true);assert!(self.shadow.confirm_terminal(&self.bank,&self.log,q["id"].as_u64().unwrap(),&o,&t,BASE+at).unwrap());}
}

#[test]fn genuine_cohort_zero_needs_original_closed_and_complete_tape(){
 let mut f=F::new();let q=f.start(4,true);let id=q["id"].as_u64().unwrap();assert_eq!(f.outcome(&q,3000).class,"unknown_or_pending_ack");f.ack(&q,4,3100);let(o,t)=f.close(&q,3150,3200,false);assert!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&t,BASE+3200).is_err());assert_eq!(f.outcome(&q,3200).filled_fraction,None);f.closed_row(&q,&o,&t);let head=f.bank.durable_head();let financial=f.bank.engine().report().unwrap();assert!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&t,BASE+3200).unwrap());let row=f.outcome(&q,3200);assert_eq!(row.class,"confirmed_zero");assert_eq!(row.filled_fraction,Some([0,4]));assert_eq!(row.reservation_principal_time_unit_ms,(4i128*400000*3200).to_string());assert_eq!(row.owned_remaining_quantity,0);assert!(row.reservation_released);assert!(!row.execution_authority);assert_eq!(f.bank.durable_head(),head);assert_eq!(f.bank.engine().report().unwrap(),financial);
}
#[test]fn real_fixed_slice_preserves_native_reservation_until_actual_ack_then_full_requested_fraction(){
 let mut f=F::new();let q=f.start(2,true);assert_eq!(q["quantity"],4);f.ack(&q,2,3100);f.fill(&q,2,0.4,3500,3600,1001);f.confirm(&q,4000,4200);let row=f.outcome(&q,4200);assert_eq!(row.native_reserved_quantity,4);assert_eq!(row.requested_quantity,2);assert_eq!(row.admitted_quantity,Some(2));assert_eq!(row.class,"confirmed_full");assert_eq!(row.filled_fraction,Some([2,2]));assert_eq!(row.reservation_principal_time_unit_ms,(4i128*400000*3100+2*400000*500).to_string());assert_eq!(row.owned_principal_time_observed_unit_ms,(2i128*400000*600).to_string());assert_eq!(row.first_execution_latency_ms,Some(500));assert_eq!(row.first_observation_latency_ms,Some(600));assert_eq!(row.maximum_fill_observation_delay_ms,Some(100));assert_eq!(f.bank.engine().wallet.quantity("101",moloch_replay::Side::Yes),2);
}
#[test]fn partial_tied_late_observations_preserve_exact_fraction_and_first_observation(){
 let mut f=F::new();let q=f.start(4,true);f.ack(&q,4,3100);f.fill(&q,1,0.4,3500,3600,1001);f.fill(&q,1,0.395,3500,5000,1002);f.confirm(&q,5100,5200);let r=f.outcome(&q,5200);assert_eq!(r.class,"confirmed_partial");assert_eq!(r.filled_fraction,Some([2,4]));assert_eq!(r.first_observation_latency_ms,Some(600));assert_eq!(r.maximum_fill_observation_delay_ms,Some(1500));assert_eq!(r.owned_principal_time_observed_unit_ms,(400000i128*1600+395000*200).to_string());let d=f.shadow.diagnostic(BASE+5200).unwrap();assert_eq!(d["priceValueLabelsCollected"],false);assert_eq!(d["fittedModel"],false);assert!(d["duplicateEvents"].as_u64().unwrap()>0);
}
#[test]fn error_expiry_and_cancel_ack_never_supply_terminal_zero(){
 let mut f=F::new();let q=f.start(4,true);let id=q["id"].as_u64().unwrap();f.log.append(json!({"kind":"error","qid":id,"at":stamp(3001),"error":{"code":"UNPROVED_NO_HTTP","mayHaveExecuted":false}})).unwrap();f.put(json!({"type":"tick"}),130000);assert_eq!(f.outcome(&q,130000).class,"unknown_or_pending_ack");assert_eq!(f.outcome(&q,130000).filled_fraction,None);
 let mut f=F::new();let q=f.start(4,true);f.ack(&q,4,3100);f.log.append(json!({"kind":"cancel_attempt","qid":q["id"],"at":stamp(3200)})).unwrap();f.log.append(json!({"kind":"cancel_ack","qid":q["id"],"receipt":F::r(format!("/orders/{}",F::actual(&q)),json!({"orderId":F::actual(&q)}),3200,3300)})).unwrap();assert_eq!(f.outcome(&q,3300).class,"acknowledged_pending");f.fill(&q,1,0.4,3350,3400,1001);f.confirm(&q,3500,3600);assert_eq!(f.outcome(&q,3600).filled_fraction,Some([1,4]));assert!(f.outcome(&q,3600).cancellation_is_informative);
}
#[test]fn changed_receipt_endpoint_tape_total_or_original_terms_cannot_confirm(){
 for case in 0..5{let mut f=F::new();let q=f.start(4,true);f.ack(&q,4,3100);f.fill(&q,1,0.4,3500,3600,1001);let(mut o,mut t)=f.close(&q,4000,4200,true);let id=q["id"].as_u64().unwrap();match case{0=>t.endpoint.push_str("&tournamentId=cup"),1=>t.data["coverage"]["complete"]=json!(false),2=>t.data["data"][0]["price"]=json!(0.395),3=>o.request_started_at=stamp(4300),_=>f.log.intents.get_mut(&id).unwrap()["spec"]["body"]["quantity"]=json!(3)}assert!(f.shadow.confirm_terminal(&f.bank,&f.log,id,&o,&t,BASE+4200).is_err(),"case {case}");assert_eq!(f.outcome(&q,4200).filled_fraction,None);}
}
#[test]fn exact_source_membership_and_duplicate_event_order_are_required(){
 let mut f=F::new();let q=f.start(4,true);let at=4000;let e=json!({"type":"tick","receivedAt":stamp(at),"processedAt":stamp(at)});f.seq+=1;f.bank.accept("moloch-live",f.seq,&e).unwrap();let mut changed=e.clone();changed["receivedAt"]=json!(stamp(at+1));assert!(f.shadow.observe_committed(&f.bank,"moloch-live",f.seq,&changed).is_err());assert!(f.shadow.diagnostic(BASE+4001).unwrap()["disabled"].is_string());assert_eq!(f.outcome(&q,4001).filled_fraction,None);
 let mut f=F::new();f.put(e.clone(),at);let before=f.shadow.diagnostic(BASE+at).unwrap()["duplicateEvents"].as_u64().unwrap();f.shadow.observe_committed(&f.bank,"moloch-live",f.seq,&e).unwrap();assert_eq!(f.shadow.diagnostic(BASE+at).unwrap()["duplicateEvents"],before+1);
}
#[test]fn restart_is_new_named_cohort_and_pending_prior_forecast_is_unscored(){
 let mut f=F::new();let q=f.start(4,true);f.ack(&q,4,3100);f.fill(&q,1,0.4,3500,3600,1001);let old=f.shadow.diagnostic(BASE+3600).unwrap()["cohortSha256"].clone();let restart=AcquisitionShadow::new(&f.bank,&f.log,&f.scope,config(),BASE+4000).unwrap();let d=restart.diagnostic(BASE+4000).unwrap();assert_ne!(d["cohortSha256"],old);assert_eq!(d["rows"],json!([]));assert_eq!(d["preCohortPendingUnscored"],json!([q["id"]]));assert!(restart.outcome(q["id"].as_u64().unwrap(),BASE+4000).is_err());
}
#[test]fn owned_capital_closes_only_on_actual_opposite_fill_and_ordinary_pool_remains_excluded(){
 let mut f=F::new();let q=f.start(4,true);f.ack(&q,4,3100);f.fill(&q,2,0.4,3500,3600,1001);f.confirm(&q,4000,4200);assert_eq!(f.outcome(&q,5000).owned_remaining_quantity,2);let other=f.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["action"]=="buy"&&q["side"]=="NO").unwrap();f.rows.clear();f.intent(&other,2,false,7000,20000);f.ack(&other,2,7100);f.fill(&other,2,0.55,7500,7600,2001);let r=f.outcome(&q,8000);assert_eq!(r.owned_remaining_quantity,0);assert_eq!(r.owned_principal_time_observed_unit_ms,(2i128*400000*4000).to_string());assert_eq!(f.bank.engine().wallet.quantity("101",moloch_replay::Side::Yes),0);assert_eq!(f.shadow.diagnostic(BASE+8000).unwrap()["excludedOrdinary"],1);assert!(f.shadow.outcome(other["id"].as_u64().unwrap(),BASE+8000).is_err());
}
#[test]fn bounded_config_and_disabled_runtime_have_no_bank_or_ordinary_model_effect(){
 let f=F::new();for c in [AcquisitionConfig{maximum_pending:0,..config()},AcquisitionConfig{retained_completed:1025,..config()},AcquisitionConfig{cohort_id:"bad/name".into(),..config()}]{assert!(c.validate().is_err());}let head=f.bank.durable_head();let financial=f.bank.engine().report().unwrap();initialize_acquisition_observer(&f.bank,&f.log,&f.scope,None,BASE).unwrap();assert!(acquisition_observer_diagnostic(&f.bank,&f.log,BASE).is_none());assert_eq!(f.bank.durable_head(),head);assert_eq!(f.bank.engine().report().unwrap(),financial);assert!(observer_diagnostic().is_none());
}

#[cfg(target_os="linux")]
#[test]fn genuine_sdk_abort_is_separate_from_zero_and_replayed_json_remains_untrusted(){
 let mut f=F::new();f.book(0,1);f.book(3000,2);let q=f.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["side"]=="YES"&&q["action"]=="buy").unwrap();f.intent(&q,4,true,3000,2999);let id=q["id"].as_u64().unwrap();let error=baal_transport_service::TransportError{code:"PERMIT_EXPIRED_OR_INVALID".into(),status:None,may_have_executed:false,retry_after_ms:0,order_id:None,api_code:None};f.log.append(json!({"kind":"error","qid":id,"at":stamp(3001),"error":error})).unwrap();let dir=f.path.join("sdk-original");std::fs::create_dir(&dir).unwrap();{let mut q=baal_transport_service::admission::AccountAdmission::open(&dir,"fixture-account","fixture-only").unwrap();q.command(json!({"op":"status","scope":"fixture-account","now":BASE+1000})).unwrap();}assert!(!std::path::Path::new("/proc/4294967295").exists());std::fs::write(dir.join("offline-account-queue.lock"),serde_json::to_vec(&json!({"scope":"fixture-account","token":"frozen-fixture-owner","pid":4294967295u64})).unwrap()).unwrap();let cfg=baal_transport_service::Config{queue_dir:dir,account_scope:"fixture-account".into(),scope:f.scope.clone(),maximum_pages:2,writes_enabled:true};let(spec,permit,attempt,error)=f.log.pre_admission_originals(id).unwrap();let proof=baal_transport_service::verify_frozen_ordinary_pre_admission(&cfg,&spec,&permit,attempt,&error).unwrap();f.log.append_aborted_before_admission(id,&proof,&stamp(3002)).unwrap();f.shadow.refresh_aborts(&f.bank,&f.log,BASE+3002).unwrap();assert_eq!(f.outcome(&q,3002).class,"proved_no_network");assert_eq!(f.outcome(&q,3002).filled_fraction,None);assert!(!f.outcome(&q,3002).reservation_released);assert!(!f.log.never_attempted(id));let replay=DispatchLog::open(&f.path.join("dispatch.ndjson")).unwrap();assert!(!replay.proved_no_network(id));let restart=AcquisitionShadow::new(&f.bank,&replay,&f.scope,config(),BASE+4000).unwrap();assert_eq!(restart.diagnostic(BASE+4000).unwrap()["preCohortPendingUnscored"],json!([id]));assert_eq!(restart.diagnostic(BASE+4000).unwrap()["completedZeroPartialFull"],json!([0,0,0]));
}
